//! The performance benchmark harness (plan M4c WP123; contract ADR 0094).
//!
//! The interfaces both harnesses share: the generated corpus
//! ([`CorpusSpec`], generated by [`corpus::Corpus`]), the metrics
//! ([`MetricName`], [`Metric`]), the budgets file `e2e/perf/budgets.json`
//! ([`Budgets`]) and the report ([`BenchReport`]).
//!
//! * [`corpus`] — the deterministic corpus (folders, people, threads,
//!   HTML, attachments, dates, flags) and typical search queries.
//! * [`mock`] — the corpus on `nail-testkit`'s mock IMAP server, in this
//!   process or in a child process (`nail-bench mock-imap`).
//! * [`run`] — the Rust metrics: initial and incremental sync, list pages,
//!   search latency, cold start, peak working set ([`memory`]).
//! * The Playwright scenarios in `e2e/perf/` measure list scrolling and the
//!   first render on the data a run leaves behind and write their metrics
//!   in the same [`Metric`] shape; `nail-bench check` merges both reports
//!   and checks the budgets.

use std::fmt::Write as _;

use serde::{Deserialize, Serialize};

pub mod corpus;
pub mod memory;
pub mod mock;
pub mod num;
pub mod run;

/// Why a benchmark run failed.
#[derive(Debug, thiserror::Error)]
pub enum BenchError {
    /// The corpus spec is invalid.
    #[error("invalid corpus spec: {0}")]
    Spec(String),
    /// The mock server failed.
    #[error("mock IMAP server: {0}")]
    Mock(String),
    /// The core answered something unexpected or the data is incomplete.
    #[error("core: {0}")]
    Core(String),
    /// A file could not be read or written.
    #[error(transparent)]
    Io(#[from] std::io::Error),
    /// A report or budgets file is not valid JSON.
    #[error(transparent)]
    Json(#[from] serde_json::Error),
}

impl From<nail_core::CoreError> for BenchError {
    fn from(error: nail_core::CoreError) -> Self {
        Self::Core(error.to_string())
    }
}

/// The generated corpus.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub struct CorpusSpec {
    /// Messages in total.
    pub messages: u64,
    /// Folders they are spread over (the Inbox gets the largest share).
    pub folders: u32,
    /// Share of messages that are replies in a thread (0..=1).
    pub thread_ratio: f64,
    /// Share of messages with an attachment (0..=1).
    pub attachment_ratio: f64,
    /// Share of HTML messages (0..=1).
    pub html_ratio: f64,
    /// Mean body size in bytes.
    pub mean_body_bytes: u32,
    /// Mean attachment size in bytes (most are smaller, a few much larger).
    #[serde(default = "default_attachment_bytes")]
    pub mean_attachment_bytes: u32,
    /// Random seed: the same spec always generates the same corpus.
    pub seed: u64,
}

fn default_attachment_bytes() -> u32 {
    60_000
}

impl CorpusSpec {
    /// The 100k-message benchmark the budgets are for.
    pub fn standard() -> Self {
        Self {
            messages: 100_000,
            folders: 40,
            thread_ratio: 0.4,
            attachment_ratio: 0.1,
            html_ratio: 0.6,
            mean_body_bytes: 4_000,
            mean_attachment_bytes: default_attachment_bytes(),
            seed: 0x4E41_494C,
        }
    }

    /// A quick corpus for CI smoke runs and tests (same shape, 2,000
    /// messages).
    pub fn small() -> Self {
        Self {
            messages: 2_000,
            folders: 8,
            ..Self::standard()
        }
    }

    /// The spec of a named corpus (`standard`, `small`).
    pub fn named(name: &str) -> Option<Self> {
        match name {
            "standard" => Some(Self::standard()),
            "small" => Some(Self::small()),
            _ => None,
        }
    }

    /// Problems (empty = valid).
    pub fn issues(&self) -> Vec<String> {
        let mut issues = Vec::new();
        if self.messages == 0 {
            issues.push("messages must be > 0".to_owned());
        }
        if self.folders == 0 {
            issues.push("folders must be > 0".to_owned());
        }
        for (name, value) in [
            ("thread-ratio", self.thread_ratio),
            ("attachment-ratio", self.attachment_ratio),
            ("html-ratio", self.html_ratio),
        ] {
            if !(0.0..=1.0).contains(&value) {
                issues.push(format!("{name} must be within 0..=1"));
            }
        }
        issues
    }
}

/// What is measured.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum MetricName {
    /// Initial sync of the whole corpus from the mock IMAP server (s).
    InitialSyncSecs,
    /// Incremental sync of 200 new Inbox messages ([`run::ARRIVALS`]; ms).
    IncrementalSyncMs,
    /// Search latency, 95th percentile over the query set (ms).
    SearchP95Ms,
    /// One message-list page (`ListMessages`), 95th percentile (ms).
    ListPageP95Ms,
    /// One conversation-list page (`ListThreads`, the default list since
    /// P2), 95th percentile (ms).
    ThreadPageP95Ms,
    /// Core start on the synced data dir until the first list answers (ms).
    ColdStartMs,
    /// Peak working set of the process (MiB).
    PeakMemoryMib,
    /// Frame time while scrolling the list, 95th percentile (ms;
    /// Playwright).
    ScrollFrameP95Ms,
    /// Frames over 50 ms while scrolling (count; Playwright).
    ScrollLongFrames,
    /// Navigation until the first message-list rows are painted on the
    /// large data set (ms; Playwright).
    FirstRenderMs,
}

impl MetricName {
    /// Every metric.
    pub const ALL: [MetricName; 10] = [
        Self::InitialSyncSecs,
        Self::IncrementalSyncMs,
        Self::SearchP95Ms,
        Self::ListPageP95Ms,
        Self::ThreadPageP95Ms,
        Self::ColdStartMs,
        Self::PeakMemoryMib,
        Self::ScrollFrameP95Ms,
        Self::ScrollLongFrames,
        Self::FirstRenderMs,
    ];

    /// Whether the Rust harness measures it (else Playwright).
    pub fn measured_in_rust(self) -> bool {
        !matches!(
            self,
            Self::ScrollFrameP95Ms | Self::ScrollLongFrames | Self::FirstRenderMs
        )
    }

    /// The wire name (`initial-sync-secs`).
    pub fn as_str(self) -> &'static str {
        match self {
            Self::InitialSyncSecs => "initial-sync-secs",
            Self::IncrementalSyncMs => "incremental-sync-ms",
            Self::SearchP95Ms => "search-p95-ms",
            Self::ListPageP95Ms => "list-page-p95-ms",
            Self::ThreadPageP95Ms => "thread-page-p95-ms",
            Self::ColdStartMs => "cold-start-ms",
            Self::PeakMemoryMib => "peak-memory-mib",
            Self::ScrollFrameP95Ms => "scroll-frame-p95-ms",
            Self::ScrollLongFrames => "scroll-long-frames",
            Self::FirstRenderMs => "first-render-ms",
        }
    }
}

/// One measurement.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Metric {
    /// What.
    pub metric: MetricName,
    /// The value (in the metric's unit).
    pub value: f64,
    /// How many samples it summarizes.
    #[serde(default)]
    pub samples: u32,
}

/// One budget: the metric must stay at or below `max`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Budget {
    /// What.
    pub metric: MetricName,
    /// The largest allowed value.
    pub max: f64,
}

/// The budgets file (`e2e/perf/budgets.json`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub struct Budgets {
    /// Which corpus the budgets are for (`standard` / `small`).
    pub corpus: String,
    /// The factor CI applies to every `max` (shared runners are slower
    /// and noisier than a developer machine; `--tolerant`). At least 1.
    #[serde(default = "one")]
    pub ci_tolerance: f64,
    /// The budgets.
    pub budgets: Vec<Budget>,
}

fn one() -> f64 {
    1.0
}

/// A budget checked against a measurement.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BudgetResult {
    /// The budget (with the effective maximum).
    pub budget: Budget,
    /// The measured value; `None` = not measured in this run.
    pub value: Option<f64>,
    /// Whether it held (unmeasured budgets do not fail).
    pub passed: bool,
}

impl Budgets {
    /// Reads the budgets JSON.
    pub fn parse(text: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(text)
    }

    /// Checks measurements against the budgets.
    pub fn check(&self, metrics: &[Metric]) -> Vec<BudgetResult> {
        self.check_with(metrics, 1.0)
    }

    /// Checks measurements against the budgets with every `max` multiplied
    /// by `factor` (at least 1; [`Self::ci_tolerance`] in CI). The results
    /// name the effective maximum.
    pub fn check_with(&self, metrics: &[Metric], factor: f64) -> Vec<BudgetResult> {
        let factor = if factor.is_finite() {
            factor.max(1.0)
        } else {
            1.0
        };
        self.budgets
            .iter()
            .map(|budget| {
                // The last measurement of a metric wins.
                let value = metrics
                    .iter()
                    .rev()
                    .find(|m| m.metric == budget.metric)
                    .map(|m| m.value);
                let max = budget.max * factor;
                BudgetResult {
                    budget: Budget {
                        metric: budget.metric,
                        max,
                    },
                    value,
                    passed: value.is_none_or(|v| v.is_finite() && v <= max),
                }
            })
            .collect()
    }

    /// Problems of the file itself (empty = fine): every metric needs
    /// exactly one positive budget, the tolerance is at least 1, the corpus
    /// is a known one.
    pub fn issues(&self) -> Vec<String> {
        let mut issues = Vec::new();
        for metric in MetricName::ALL {
            let n = self.budgets.iter().filter(|b| b.metric == metric).count();
            if n != 1 {
                issues.push(format!("{} has {n} budgets", metric.as_str()));
            }
        }
        for b in &self.budgets {
            if !(b.max.is_finite() && b.max > 0.0) {
                issues.push(format!("{} has a non-positive budget", b.metric.as_str()));
            }
        }
        if !(self.ci_tolerance.is_finite() && self.ci_tolerance >= 1.0) {
            issues.push("ci-tolerance must be at least 1".to_owned());
        }
        if CorpusSpec::named(&self.corpus).is_none() {
            issues.push(format!("unknown corpus {:?}", self.corpus));
        }
        issues
    }
}

/// The result of one benchmark run.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BenchReport {
    /// The corpus.
    pub corpus: CorpusSpec,
    /// What was measured.
    pub metrics: Vec<Metric>,
    /// The budgets checked.
    pub results: Vec<BudgetResult>,
    /// What the run found besides the metrics (Rust runs).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub facts: Option<run::RunFacts>,
    /// Remarks (e.g. a corpus other than the budgets' one).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub notes: Vec<String>,
}

impl BenchReport {
    /// Whether every measured budget held.
    pub fn passed(&self) -> bool {
        self.results.iter().all(|r| r.passed)
    }

    /// A plain-text table of the results (developer output of the
    /// benchmark tool, not user-facing).
    pub fn table(&self) -> String {
        let mut out = String::new();
        let _ = writeln!(
            out,
            "corpus: {} messages in {} folders (seed {:#x})",
            self.corpus.messages, self.corpus.folders, self.corpus.seed
        );
        let _ = writeln!(
            out,
            "{:<22} {:>12} {:>12}  result",
            "metric", "value", "budget"
        );
        for r in &self.results {
            let value = r
                .value
                .map_or_else(|| "-".to_owned(), |v| format!("{v:.1}"));
            let verdict = match (r.value, r.passed) {
                (None, _) => "not measured",
                (Some(_), true) => "ok",
                (Some(_), false) => "OVER BUDGET",
            };
            let _ = writeln!(
                out,
                "{:<22} {:>12} {:>12.1}  {verdict}",
                r.budget.metric.as_str(),
                value,
                r.budget.max
            );
        }
        for note in &self.notes {
            let _ = writeln!(out, "note: {note}");
        }
        out
    }
}

/// Merges metric lists (later lists replace earlier measurements of the
/// same metric).
pub fn merge_metrics(lists: &[Vec<Metric>]) -> Vec<Metric> {
    let mut out: Vec<Metric> = Vec::new();
    for list in lists {
        for m in list {
            out.retain(|o| o.metric != m.metric);
            out.push(m.clone());
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use pretty_assertions::assert_eq;

    const BUDGETS: &str = include_str!("../../../e2e/perf/budgets.json");

    #[test]
    fn the_budgets_file_covers_every_metric() {
        let budgets = Budgets::parse(BUDGETS).unwrap();
        assert_eq!(budgets.corpus, "standard");
        for metric in MetricName::ALL {
            assert!(
                budgets.budgets.iter().any(|b| b.metric == metric),
                "{metric:?} has no budget"
            );
        }
        assert_eq!(budgets.budgets.len(), MetricName::ALL.len());
        assert_eq!(budgets.issues(), Vec::<String>::new());
        assert!(budgets.ci_tolerance >= 1.0 && budgets.ci_tolerance <= 3.0);
    }

    #[test]
    fn wire_names_match_serde() {
        for metric in MetricName::ALL {
            assert_eq!(
                serde_json::to_value(metric).unwrap(),
                serde_json::json!(metric.as_str())
            );
        }
    }

    #[test]
    fn budgets_check_measurements() {
        let budgets = Budgets::parse(BUDGETS).unwrap();
        let metrics = [
            Metric {
                metric: MetricName::SearchP95Ms,
                value: 10.0,
                samples: 50,
            },
            Metric {
                metric: MetricName::ColdStartMs,
                value: 1e9,
                samples: 1,
            },
        ];
        let results = budgets.check(&metrics);
        let search = results
            .iter()
            .find(|r| r.budget.metric == MetricName::SearchP95Ms)
            .unwrap();
        assert!(search.passed);
        let cold = results
            .iter()
            .find(|r| r.budget.metric == MetricName::ColdStartMs)
            .unwrap();
        assert!(!cold.passed);
        let unmeasured = results
            .iter()
            .find(|r| r.budget.metric == MetricName::PeakMemoryMib)
            .unwrap();
        assert!(unmeasured.passed && unmeasured.value.is_none());
        let report = BenchReport {
            corpus: CorpusSpec::small(),
            metrics: metrics.to_vec(),
            results,
            facts: None,
            notes: vec!["a note".into()],
        };
        assert!(!report.passed());
        let table = report.table();
        assert!(table.contains("OVER BUDGET") && table.contains("not measured"));
        assert!(table.contains("note: a note"));
    }

    #[test]
    #[expect(
        clippy::float_cmp,
        reason = "budgets are scaled by exact factors (1.5, 1.0), the results are exact"
    )]
    fn tolerance_widens_every_budget() {
        let budgets = Budgets {
            corpus: "standard".into(),
            ci_tolerance: 1.5,
            budgets: vec![Budget {
                metric: MetricName::SearchP95Ms,
                max: 100.0,
            }],
        };
        let over = [Metric {
            metric: MetricName::SearchP95Ms,
            value: 140.0,
            samples: 1,
        }];
        assert!(!budgets.check(&over)[0].passed);
        let tolerant = budgets.check_with(&over, budgets.ci_tolerance);
        assert!(tolerant[0].passed);
        assert_eq!(tolerant[0].budget.max, 150.0);
        // Factors below 1 or not finite never tighten a budget.
        assert_eq!(budgets.check_with(&over, 0.5)[0].budget.max, 100.0);
        assert_eq!(budgets.check_with(&over, f64::NAN)[0].budget.max, 100.0);
        // NaN measurements fail.
        let nan = [Metric {
            metric: MetricName::SearchP95Ms,
            value: f64::NAN,
            samples: 1,
        }];
        assert!(!budgets.check(&nan)[0].passed);
        assert!(!budgets.issues().is_empty(), "missing metrics are reported");
    }

    #[test]
    #[expect(clippy::float_cmp, reason = "merging copies measured values unchanged")]
    fn later_reports_replace_earlier_measurements() {
        let a = vec![
            Metric {
                metric: MetricName::ColdStartMs,
                value: 1.0,
                samples: 1,
            },
            Metric {
                metric: MetricName::SearchP95Ms,
                value: 5.0,
                samples: 1,
            },
        ];
        let b = vec![Metric {
            metric: MetricName::ColdStartMs,
            value: 2.0,
            samples: 1,
        }];
        let merged = merge_metrics(&[a, b]);
        assert_eq!(merged.len(), 2);
        assert_eq!(
            merged
                .iter()
                .find(|m| m.metric == MetricName::ColdStartMs)
                .unwrap()
                .value,
            2.0
        );
    }

    #[test]
    fn corpus_specs() {
        assert_eq!(CorpusSpec::standard().issues().len(), 0);
        assert_eq!(CorpusSpec::standard().messages, 100_000);
        assert_eq!(CorpusSpec::small().issues().len(), 0);
        assert_eq!(CorpusSpec::named("small"), Some(CorpusSpec::small()));
        assert_eq!(CorpusSpec::named("huge"), None);
        let bad = CorpusSpec {
            messages: 0,
            html_ratio: 2.0,
            ..CorpusSpec::small()
        };
        assert_eq!(bad.issues().len(), 2);
        assert!(MetricName::InitialSyncSecs.measured_in_rust());
        assert!(!MetricName::ScrollLongFrames.measured_in_rust());
        assert!(!MetricName::FirstRenderMs.measured_in_rust());
        // Older spec JSON without the attachment size still reads.
        let mut json = serde_json::to_value(CorpusSpec::small()).unwrap();
        json.as_object_mut()
            .unwrap()
            .remove("mean-attachment-bytes");
        let spec: CorpusSpec = serde_json::from_value(json).unwrap();
        assert_eq!(spec, CorpusSpec::small());
    }
}
